-- GenDB engine variant Q22-wrapped_tables: template q22.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  cntrycode,
  COUNT(*) AS numcust,
  SUM(c_acctbal) AS totacctbal
FROM (
  SELECT
    SUBSTRING(c_phone FROM 1 FOR 2) AS cntrycode,
    c_acctbal
  FROM (
    SELECT
      *
    FROM customer
  ) AS customer
  WHERE
    SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    AND c_acctbal > (
      SELECT
        AVG(c_acctbal)
      FROM (
        SELECT
          *
        FROM customer
      ) AS customer
      WHERE
        c_acctbal > 0.00
        AND SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    )
    AND NOT EXISTS(
      SELECT
        *
      FROM (
        SELECT
          *
        FROM orders
      ) AS orders
      WHERE
        o_custkey = c_custkey
    )
) AS custsale
GROUP BY
  cntrycode
ORDER BY
  cntrycode
